def find_connected_components(arr, color, conn=8):
    """Find all connected components of a given color in 8-connectivity"""
    rows, cols = arr.shape
    visited = np.zeros((rows, cols), dtype=bool)
    components = []

    for r in range(rows):
        for c in range(cols):
            if arr[r, c] == color and not visited[r, c]:
                comp = set()
                def bfs(cr, cc):
                    stack = [(cr, cc)]
                    visited[cr, cc] = True
                    comp.add((cr, cc))
                    while stack:
                        r, c = stack.pop()
                        # 8-connectivity
                        for dr in [-1, 0, 1]:
                            for dc in [-1, 0, 1]:
                                if dr == 0 and dc == 0:
                                    continue
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < rows and 0 <= nc < cols:
                                    if arr[nr, nc] == color and not visited[nr, nc]:
                                        visited[nr, nc] = True
                                        comp.add((nr, nc))
                                        stack.append((nr, nc))
                bfs(r, c)
                components.append(comp)
    return components

# Check number of components for each color
for color in [3, 5]:
    comp = find_connected_components(grid_np, color)
    print(f"Color {color} has {len(comp)} connected components")

